// Düğmeyle parlaklık: potansiyometre LED'in parlaklığını ayarlar.
const int POT_PIN = A0;     // potansiyometrenin orta bacağı
const int LED_PIN = 9;      // PWM pini (kartta ~ işareti var)
const int BEKLE_MS = 100;   // iki okuma arası bekleme

void setup() {
  Serial.begin(9600);
  pinMode(LED_PIN, OUTPUT);
}

void loop() {
  int deger = analogRead(POT_PIN);              // 0-1023
  int parlaklik = map(deger, 0, 1023, 0, 255);  // PWM 0-255 ister
  analogWrite(LED_PIN, parlaklik);

  Serial.print("Pot: ");
  Serial.print(deger);
  Serial.print("  Parlaklik: ");
  Serial.println(parlaklik);
  delay(BEKLE_MS);
}
